observation_driver_extension:
extends "res://tools/first30_probe.gd"
func ui_snapshot() -> Dictionary:
 var controls: Array=[]
 for node in root.find_children("*","Control",true,false):
  if not node.is_visible_in_tree(): continue
  if node is Label or node is Button or node is LineEdit or node is OptionButton:
   var rect: Rect2=node.get_global_rect()
   controls.append({"path":str(node.get_path()),"kind":node.get_class(),"text":str(node.get("text")),"tooltip":node.tooltip_text,"rect":[rect.position.x,rect.position.y,rect.size.x,rect.size.y],"disabled":bool(node.get("disabled")) if node is BaseButton else false,"inside":root.get_visible_rect().intersects(rect)})
 var merchant: String=game.town_services.market.actor_id
 return {"last_spell_source":game.player.input_controller.last_spell_source,"wheel_last_source":game.player.material_wheel.last_source,"wheel_entries":game.player.material_wheel.entries if game.player.material_wheel.visible else [],"viewport":[root.size.x,root.size.y],"controls":controls,"selected_inventory":game.inventory_screen.selected if game.inventory_screen.visible else "","production":game.session.production.snapshot(),"merchant":game.session.inventory.material_amounts(merchant),"nutrition":game.survival.needs.nutrition,"hydration":game.survival.needs.hydration,"fatigue":game.survival.needs.fatigue}
func execute(request: Dictionary) -> void:
 var op:=str(request.get("op","state"))
 if op not in ["inspect","resize","scroll","type"]:
  await super.execute(request)
  return
 match op:
  "resize": root.size=Vector2i(int(request.width),int(request.height)); await settle(8)
  "scroll":
   var point:=Vector2(request.point[0],request.point[1])
   if DisplayServer.get_name()!="headless": Input.warp_mouse(point)
   var motion:=InputEventMouseMotion.new(); motion.position=point; motion.global_position=point
   Input.parse_input_event(motion); await settle(2)
   for i in range(int(request.get("steps",1))):
    var event:=InputEventMouseButton.new(); event.position=point; event.global_position=point; event.button_index=MOUSE_BUTTON_WHEEL_UP if request.get("up",false) else MOUSE_BUTTON_WHEEL_DOWN; event.pressed=true
    Input.parse_input_event(event); await settle(2)
    event=event.duplicate(); event.pressed=false; Input.parse_input_event(event); await settle(2)
  "type":
   for character in str(request.text):
    var event:=InputEventKey.new(); event.unicode=character.unicode_at(0); event.pressed=true
    Input.parse_input_event(event); Input.flush_buffered_events(); await settle(1)
    event=event.duplicate(); event.pressed=false; Input.parse_input_event(event); await settle(1)
 var result:=snapshot(); result["id"]=request.id; result["error"]=""; result["ui"]=ui_snapshot()
 if request.has("capture"): await screen(str(request.capture))
 write_json("result.json",result); write_json("step_%04d.json"%int(request.id),{"request":request,"state":result})
 print("FRICTION ",request.id," ",op," pos=",game.player.position," hp=",game.player.health_component.hp)
 busy=false
